#!/usr/bin/env bun
/**
 * PLAN_V3 3.2 — build the single-file ESM release bundle.
 *
 * Artifact: release/psy-foundation.esm.js — every workspace package's public
 * API as one importable file (see scripts/bundle-entry.ts). Together with the
 * generated worklet (apps/web/public/worklets/psy4-processor.js) this is one
 * of the two artifacts zip-era consumers actually pin.
 *
 * Reproducibility gate (charter): two consecutive builds must be
 * byte-identical — the script refuses to exit 0 if they are not.
 *
 * Usage:
 *   bun scripts/build-bundle.mjs
 *   bun run build:bundle
 */

import { createHash } from 'node:crypto'
import { mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const entry = join(repoRoot, 'scripts/bundle-entry.ts')
const outdir = join(repoRoot, 'release')
const outfile = join(outdir, 'psy-foundation.esm.js')

const versionTs = readFileSync(join(repoRoot, 'packages/dsp/src/version.ts'), 'utf8')
const versionMatch = versionTs.match(/FOUNDATION_VERSION\s*=\s*'([^']+)'/)
if (!versionMatch) {
  console.error(
    'bundle build FAILED: could not read FOUNDATION_VERSION from packages/dsp/src/version.ts'
  )
  process.exit(1)
}
const FOUNDATION_VERSION = versionMatch[1]

async function buildOnce() {
  let result
  try {
    result = await Bun.build({
      entrypoints: [entry],
      target: 'browser',
      format: 'esm',
      minify: false,
      naming: 'psy-foundation.esm.js',
    })
  } catch (err) {
    console.error('bundle build FAILED (Bun.build threw):')
    for (const log of err?.errors ?? []) console.error(String(log))
    console.error(String(err))
    process.exit(1)
  }
  if (!result.success) {
    console.error('bundle build FAILED:')
    for (const log of result.logs) console.error(String(log))
    process.exit(1)
  }
  return result.outputs[0]
}

console.log(`building ${entry} → ${outfile} (foundation v${FOUNDATION_VERSION})`)
mkdirSync(outdir, { recursive: true })

// Build once, write to disk with a version header, then build AGAIN from the
// same source and compare — nondeterministic toolchains must not ship.
const output1 = await buildOnce()
const code1 = await output1.text()
const artifact = `/* psy-foundation.esm.js — GENERATED by scripts/build-bundle.mjs — DO NOT EDIT. */\n/* PSY-FOUNDATION-VERSION: ${FOUNDATION_VERSION} */\n${code1}`
writeFileSync(outfile, artifact)

const output2 = await buildOnce()
const code2 = await output2.text()

const md5 = createHash('md5').update(artifact).digest('hex')
const bytes = statSync(outfile).size

if (code1 !== code2) {
  console.error('bundle build FAILED: output is NOT deterministic across builds')
  console.error(`  md5(first)  = ${md5}`)
  console.error(`  md5(second) = ${createHash('md5').update(code2).digest('hex')}`)
  process.exit(1)
}

// ── Assertion: the artifact actually parses and exports the namespaces ──────
const exportNames = [...code1.matchAll(/export\s*\{([^}]+)\}/g)].map((m) => m[1]).join(',')
const expected = [
  'dsp',
  'music',
  'transport',
  'protocol',
  'deviceSdk',
  'analysis',
  'learning',
  'material',
  'scheduler',
  'fixtures',
]
for (const name of expected) {
  if (!exportNames.includes(name)) {
    console.error(`bundle build FAILED: expected namespace export "${name}" not found in output`)
    process.exit(1)
  }
}

console.log(
  `bundle build OK (${bytes} bytes, md5=${md5}, deterministic ×2, exports: ${expected.join(', ')})`
)
